 "content": "def transform(grid):
    # Unvalidated best-effort: highlight cells where two same-color marks lie
    # exactly two apart on a row or column, or a marker has another at its
    # diagonal neighboring crossing.
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    mark = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != mark:
                continue
            for dr, dc in ((0, 1), (1, 0)):
                rr, cc = r + 2*dr, c + 2*dc
                if rr < h and cc < w and grid[rr][cc] == mark and grid[r+dr][c+dc] == bg:
                    out[r+dr][c+dc] = 2
    return out

